-- Geo subdivisions (ISO 3166-2) + cities.region_code.
--
-- WHY
-- A city's state/province/region lived only in `cities.region_name`, free
-- text: "California", "Bayern" and "Bavaria", "Principality of Asturias",
-- GeoNames admin1 numbers ("27" is São Paulo, "02" New South Wales, "03"
-- Dubai), ISO suffixes ("VLG"), and on 1,849 live cities nothing at all.
-- Nothing could compare, display or key on it. And `cities` holds at most one
-- row per (name, country), so Portland ME/OR, Springfield, Charleston … cannot
-- both exist — the region is the missing part of a city's identity.
--
-- This is step 2a of the region rework: the vocabulary, the column, the
-- resolver and the backfill. Uniqueness on (country, region, name) and the
-- "City, ST · Country" display come in later steps.
--
-- WHAT THIS DOES
-- 1. `public.geo_subdivisions` — 5,296 ISO 3166-2 subdivisions generated from
--    dr5hn/countries-states-cities-database by
--    scripts/data-quality/generate-geo-subdivisions.mjs (regenerate, never
--    hand-edit). Keeps the hierarchy (`parent_code`: BE provinces → regions,
--    FR departments → regions) and dr5hn's `fips_code`, which equals the
--    GeoNames admin1 code for most countries.
-- 2. `resolve_region_code(country_code, text)` → the FIRST-LEVEL subdivision
--    code, or NULL. Tries, in order: the ISO code or its suffix, the FIPS /
--    GeoNames number (digits only), the name/native/translation, the name with
--    generic words ("Province", "Region of", "Oblast") removed. Every arm must
--    resolve to exactly ONE first-level unit or the answer is NULL — dr5hn
--    lists some units twice under old and new codes (Navarre ES-NA/ES-NC,
--    Corsica FR-20R/FR-2A), and guessing between them is how a wrong code
--    becomes permanent. Indonesian island groups (type 'geographical unit',
--    ID-JW "Jawa") sit at the same level as the provinces and are never a
--    city's region, so they are excluded from matching.
-- 3. `cities.region_code` (FK) kept in sync by a BEFORE trigger whenever
--    `region_name` is written, named `trg_cities_ab_*` so it runs AFTER
--    trg_cities_aa_split_name (which may fill region_name from a qualifier).
-- 4. One-shot backfill from the existing region_name.
--
-- MEASURED BEFORE WRITING (this file run in PGlite against all 5,647 live
-- cities, 2026-10-03)
-- * 3,798 carry a region_name; 3,623 resolve (95.4%). The 175 that do not are
--   Bangladesh GeoNames codes dr5hn does not carry (81 rows), territories
--   whose "region" is their own name (Guam, Curaçao, Christmas Island),
--   genuinely ambiguous names ("Aegean" — North or South?), and dr5hn's
--   duplicate old/new codes (Cantabria, Moscow). All stay NULL by design.
-- * 45 English exonyms dr5hn lacks ("Brittany", "Normandy", "West Java",
--   "Masovian Voivodeship" …) are added as aliases by the generator's
--   EXTRA_ALIASES, each checked against the dr5hn row for its code.
-- * FIPS matches are as trustworthy as name matches: the resolved unit is one
--   of the three nearest subdivision centroids for 98.4% of FIPS matches vs
--   95.1% of name matches. The single FIPS outlier (Paulo Afonso → Bahia,
--   rank 7) is correct — a border town in a very large state.
-- * 1,849 cities have no region_name at all; filling those needs a geocoder
--   or Wikidata P131 and is its own step.

-- cities is read continuously; ALTER TABLE and CREATE TRIGGER on it need an
-- ACCESS EXCLUSIVE lock. A 5s timeout lost that race in the prod dry run.
-- 30s waits out a busy moment and still fails rather than queueing readers
-- behind it indefinitely.
set local lock_timeout = '30s';
-- The backfill writes ~3,600 cities and each UPDATE fans out through
-- trg_sync_geo_spine into search_reindex_queue: measured 7.4 ms/row in a
-- rolled-back prod dry run (1,059 rows in 7.8 s), so ~27 s for the full set.
set local statement_timeout = '5min';
select set_config('app.actor', 'migration:99991790994947_geo_subdivisions_region_code', true);

-- ---------------------------------------------------------------------------
-- 1. Vocabulary
-- ---------------------------------------------------------------------------
create table if not exists public.geo_subdivisions (
  code             text primary key check (code ~ '^[A-Z]{2}-[A-Z0-9]{1,4}$'),
  country_code     text not null check (country_code ~ '^[A-Z]{2}$'),
  name             text not null,
  subdivision_type text,
  parent_code      text,
  fips_code        text,
  wikidata_qid     text,
  latitude         numeric,
  longitude        numeric,
  aliases          text[] not null default '{}',
  name_keys        text[] not null default '{}',
  core_keys        text[] not null default '{}',
  created_at       timestamptz not null default now()
);

comment on table public.geo_subdivisions is
  'ISO 3166-2 subdivisions (dr5hn states.json, generated by scripts/data-quality/generate-geo-subdivisions.mjs). '
  'parent_code links second-level units to their first-level unit. Reference data — regenerate, never hand-edit.';

create index if not exists geo_subdivisions_country_idx on public.geo_subdivisions (country_code);

alter table public.geo_subdivisions enable row level security;
drop policy if exists geo_subdivisions_read on public.geo_subdivisions;
create policy geo_subdivisions_read on public.geo_subdivisions for select using (true);
grant select on public.geo_subdivisions to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. Normalisation + resolver
-- ---------------------------------------------------------------------------
create or replace function public.geo_subdivision_norm(p text)
returns text
language sql
stable
set search_path to 'public'
as $$
  select nullif(btrim(regexp_replace(public.city_name_key(p), '[^[:alnum:]]+', ' ', 'g')), '');
$$;

-- Generic words that carry no identity: "Region of Murcia" = "Murcia",
-- "Department of Cusco" = "Cusco", "Kyiv Oblast" = "Kyiv".
create or replace function public.geo_subdivision_core(p text)
returns text
language sql
stable
set search_path to 'public'
as $$
  select nullif(btrim(regexp_replace(regexp_replace(public.geo_subdivision_norm(p),
    '\m(province|provincia|region|state|prefecture|oblast|voivodeship|department|departement|governorate|district|county|krai|autonomous community|community|of|the|de|del|la|le|capital|municipality|city)\M',
    ' ', 'g'), '\s+', ' ', 'g')), '');
$$;

-- First-level ancestor of a subdivision (itself when it has no parent).
create or replace function public.geo_subdivision_root(p_code text)
returns text
language sql
stable
set search_path to 'public'
as $$
  with recursive up as (
    select code, parent_code, 0 as depth from public.geo_subdivisions where code = p_code
    union all
    select s.code, s.parent_code, up.depth + 1
      from public.geo_subdivisions s join up on s.code = up.parent_code
     where up.depth < 5
  )
  select code from up where parent_code is null or not exists (
    select 1 from public.geo_subdivisions s where s.code = up.parent_code)
  order by depth desc limit 1;
$$;

create or replace function public.resolve_region_code(p_country_code text, p_text text)
returns text
language plpgsql
stable
set search_path to 'public'
as $$
declare
  v_cc   text := upper(btrim(coalesce(p_country_code, '')));
  v_raw  text := btrim(coalesce(p_text, ''));
  v_norm text := public.geo_subdivision_norm(p_text);
  v_core text := public.geo_subdivision_core(p_text);
  v_hits text[];
begin
  if v_cc = '' or v_raw = '' then
    return null;
  end if;

  -- (a) ISO code or its suffix ("US-CA", "CA", "VLG")
  select array_agg(distinct public.geo_subdivision_root(code)) into v_hits
    from public.geo_subdivisions
   where country_code = v_cc and coalesce(subdivision_type, '') <> 'geographical unit'
     and (upper(code) = upper(v_raw) or upper(split_part(code, '-', 2)) = upper(v_raw));
  if cardinality(v_hits) = 1 then return v_hits[1]; end if;
  if cardinality(v_hits) > 1 then return null; end if;

  -- (b) FIPS / GeoNames admin1 number — digits only, never for a name
  if v_raw ~ '^[0-9]+$' then
    select array_agg(distinct public.geo_subdivision_root(code)) into v_hits
      from public.geo_subdivisions
     where country_code = v_cc and coalesce(subdivision_type, '') <> 'geographical unit' and fips_code = v_raw;
    if cardinality(v_hits) = 1 then return v_hits[1]; end if;
    return null;
  end if;

  -- (c) name / native / translation
  if v_norm is not null then
    select array_agg(distinct public.geo_subdivision_root(code)) into v_hits
      from public.geo_subdivisions
     where country_code = v_cc and coalesce(subdivision_type, '') <> 'geographical unit' and v_norm = any (name_keys);
    if cardinality(v_hits) = 1 then return v_hits[1]; end if;
    if cardinality(v_hits) > 1 then return null; end if;
  end if;

  -- (d) name without generic words
  if v_core is not null then
    select array_agg(distinct public.geo_subdivision_root(code)) into v_hits
      from public.geo_subdivisions
     where country_code = v_cc and coalesce(subdivision_type, '') <> 'geographical unit' and v_core = any (core_keys);
    if cardinality(v_hits) = 1 then return v_hits[1]; end if;
  end if;

  return null;
end;
$$;

grant execute on function public.resolve_region_code(text, text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Seed
-- ---------------------------------------------------------------------------
-- generated by scripts/data-quality/generate-geo-subdivisions.mjs from dr5hn states.json (5296 rows)
on conflict (code) do nothing;

-- Parent links point at codes in the same table; drop any that dr5hn names
-- but does not list, rather than inventing a hierarchy.
update public.geo_subdivisions s
   set parent_code = null
 where parent_code is not null
   and not exists (select 1 from public.geo_subdivisions p where p.code = s.parent_code);

do $fk$
begin
  if not exists (select 1 from pg_constraint where conname = 'geo_subdivisions_parent_fk') then
    alter table public.geo_subdivisions
      add constraint geo_subdivisions_parent_fk foreign key (parent_code)
      references public.geo_subdivisions (code) on update cascade on delete set null;
  end if;
end
$fk$;

-- Precomputed match keys (name + native + translations).
update public.geo_subdivisions s
   set name_keys = k.name_keys,
       core_keys = k.core_keys
  from (
    select code,
           array_remove(array_agg(distinct public.geo_subdivision_norm(n)), null) as name_keys,
           array_remove(array_agg(distinct public.geo_subdivision_core(n)), null) as core_keys
      from public.geo_subdivisions, unnest(array[name] || aliases) as n
     group by code
  ) k
 where k.code = s.code;

-- ---------------------------------------------------------------------------
-- 3. cities.region_code + sync trigger
-- ---------------------------------------------------------------------------
alter table public.cities
  add column if not exists region_code text
    references public.geo_subdivisions (code) on update cascade on delete set null;

comment on column public.cities.region_code is
  'First-level ISO 3166-2 subdivision (geo_subdivisions.code). Derived from region_name by trg_cities_ab_region_code; '
  'NULL when region_name is empty or does not resolve to exactly one unit.';

create index if not exists cities_region_code_idx on public.cities (region_code);

create or replace function public.cities_sync_region_code()
returns trigger
language plpgsql
set search_path to 'public'
as $$
declare
  v_cc text;
begin
  -- Explicit writes of region_code win; otherwise derive from region_name
  -- whenever that is (re)written or the country changes.
  if tg_op = 'UPDATE'
     and new.region_code is distinct from old.region_code then
    return new;
  end if;
  if tg_op = 'INSERT'
     or new.region_name is distinct from old.region_name
     or new.country_id is distinct from old.country_id then
    select code into v_cc from public.countries where id = new.country_id;
    new.region_code := public.resolve_region_code(v_cc, new.region_name);
  end if;
  return new;
end;
$$;

drop trigger if exists trg_cities_ab_region_code on public.cities;
create trigger trg_cities_ab_region_code
  before insert or update on public.cities
  for each row execute function public.cities_sync_region_code();

-- ---------------------------------------------------------------------------
-- 4. Backfill from existing region_name (only rows that resolve are written;
--    each UPDATE fans out through trg_sync_geo_spine, so batch at 500).
-- ---------------------------------------------------------------------------
do $backfill$
declare
  v_n     int;
  v_total int := 0;
begin
  loop
    with todo as (
      select c.id, public.resolve_region_code(co.code, c.region_name) as rc
        from public.cities c
        join public.countries co on co.id = c.country_id
       where c.region_code is null
         and nullif(btrim(c.region_name), '') is not null
         and c.duplicate_of_id is null
    ), pick as (
      select id, rc from todo where rc is not null limit 500
    )
    update public.cities c
       set region_code = pick.rc
      from pick
     where c.id = pick.id;
    get diagnostics v_n = row_count;
    v_total := v_total + v_n;
    exit when v_n = 0;
  end loop;
  raise notice 'region_code backfilled on % cities', v_total;
end
$backfill$;

-- ---------------------------------------------------------------------------
-- Postconditions
-- ---------------------------------------------------------------------------
do $verify$
declare
  v_n int;
begin
  -- P1: the vocabulary is loaded and carries the first-level units we rely on.
  select count(*) into v_n from public.geo_subdivisions;
  if v_n < 5000 then
    raise exception 'P1 failed: geo_subdivisions has % rows', v_n;
  end if;
  select count(*) into v_n from public.geo_subdivisions
   where code in ('US-CA','US-ME','US-OR','DE-BY','AU-NSW','BR-SP','BE-VLG','GB-ENG');
  if v_n <> 8 then
    raise exception 'P1 failed: % of 8 reference subdivisions present', v_n;
  end if;

  -- P2: resolver positive controls, one per arm.
  if public.resolve_region_code('US', 'California')       is distinct from 'US-CA'  then raise exception 'P2 failed: name arm'; end if;
  if public.resolve_region_code('DE', 'Bayern')           is distinct from 'DE-BY'  then raise exception 'P2 failed: alias arm'; end if;
  if public.resolve_region_code('AU', '02')               is distinct from 'AU-NSW' then raise exception 'P2 failed: fips arm'; end if;
  if public.resolve_region_code('BR', '27')               is distinct from 'BR-SP'  then raise exception 'P2 failed: fips arm BR'; end if;
  if public.resolve_region_code('BE', 'VLG')              is distinct from 'BE-VLG' then raise exception 'P2 failed: code arm'; end if;
  if public.resolve_region_code('JP', 'Aichi Prefecture') is distinct from 'JP-23'  then raise exception 'P2 failed: core arm'; end if;
  if public.resolve_region_code('BE', 'Antwerp')          is distinct from 'BE-VLG' then raise exception 'P2 failed: province climbs to region'; end if;

  -- P3: negative controls — never guess.
  if public.resolve_region_code('US', 'Nowhere Land') is not null then raise exception 'P3 failed: invented a region'; end if;
  if public.resolve_region_code('US', '99')           is not null then raise exception 'P3 failed: unknown number resolved'; end if;
  if public.resolve_region_code('GB', 'South Carolina') is not null then raise exception 'P3 failed: crossed a border'; end if;

  -- P4: the backfill reached the bulk of the cohort (measured 3,517 of 3,798).
  select count(*) into v_n from public.cities where region_code is not null and duplicate_of_id is null;
  if v_n < 3000 then
    raise exception 'P4 failed: only % cities carry region_code', v_n;
  end if;

  -- P5: every assigned code belongs to the city's own country (or a dr5hn
  --     overseas alias of it, e.g. FR-973 filed under GF).
  select count(*) into v_n
    from public.cities c
    join public.countries co on co.id = c.country_id
    join public.geo_subdivisions s on s.code = c.region_code
   where s.country_code <> co.code;
  if v_n <> 0 then
    raise exception 'P5 failed: % cities carry another country''s region', v_n;
  end if;

  -- P6: the trigger keeps it in sync.
  if not exists (select 1 from pg_trigger where tgname = 'trg_cities_ab_region_code'
                    and tgrelid = 'public.cities'::regclass and tgenabled <> 'D') then
    raise exception 'P6 failed: trg_cities_ab_region_code missing or disabled';
  end if;
end
$verify$;
